package lk.ac.sliit.ridelink.ride.infrastructure.client.fare;
import lk.ac.sliit.ridelink.ride.application.port.out.FareCalculationPort; import lk.ac.sliit.ridelink.ride.application.usecase.ExternalServiceException; import lk.ac.sliit.ridelink.ride.domain.enums.VehicleType; import lk.ac.sliit.ridelink.ride.infrastructure.client.ClientSupport; import org.springframework.beans.factory.annotation.Qualifier; import org.springframework.http.HttpStatusCode; import org.springframework.stereotype.Component; import org.springframework.web.client.*; import java.math.BigDecimal;
@Component public class FarePaymentServiceClient implements FareCalculationPort {record FareRequest(VehicleType vehicleType,BigDecimal distanceKm){}record FareResponse(BigDecimal totalFare){}private final RestClient client;public FarePaymentServiceClient(@Qualifier("fareRestClient") RestClient c){client=c;}public BigDecimal estimate(VehicleType t,BigDecimal d){return calculate(t,d);}public BigDecimal finalFare(VehicleType t,BigDecimal d){return calculate(t,d);}private BigDecimal calculate(VehicleType t,BigDecimal d){try{FareResponse r=client.post().uri("/api/fares/estimate").body(new FareRequest(t,d)).retrieve().onStatus(HttpStatusCode::isError,(q,s)->ClientSupport.status("Fare Service",s.getStatusCode())).body(FareResponse.class);if(r==null||r.totalFare()==null)throw new ExternalServiceException("Fare Service returned an invalid response",false,null);return r.totalFare();}catch(ExternalServiceException e){throw e;}catch(RestClientException e){throw ClientSupport.failure("Fare Service",e);}}}
